/**
 * 邮件品牌 logo：apps/web/public/favicon.jpeg 的 base64 内嵌（不用外链——
 * 多数邮件客户端默认屏蔽远程图片，内嵌 data URI 始终可见）。
 * 体积约 77KB base64，仅随邮件 HTML 发送，不影响接口延迟。
 *
 * 更换图片后重新生成：
 *   base64 -w0 apps/web/public/favicon.jpeg > /tmp/b64.txt
 *   （替换下方字符串）
 */
export const BRAND_LOGO_DATA_URI =
  'data:image/jpeg;base64,'
